def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
    opp_d = n - opp_c

    if n < 5:
        if opp_d >= 3:
            return 'D'
        return 'C'

    d5 = 0
    for a, b in history[-5:]:
        if b == 'D':
            d5 += 1

    d10 = 0
    for a, b in history[-10:]:
        if b == 'D':
            d10 += 1

    if opp_c > opp_d:
        if last_opp == 'C':
            if d10 >= 7 and opp_d > 5:
                return 'D'
            return 'C'

        if opp_c >= opp_d + 6 and opp_d <= 3 and d5 <= 3:
            return 'C'

        if (last_my == 'C' and n >= 2 and history[-2][0] == 'D'
                and history[-2][1] == 'C' and opp_c >= opp_d + 2):
            return 'C'

        if last_my == 'D' and opp_c >= opp_d + 5 and d5 <= 5 and d10 <= 8:
            return 'C'

        if d10 <= 1 and opp_c >= opp_d + 8:
            return 'C'

        return 'D'

    if last_opp == 'C':
        if d5 == 0 and opp_c + 4 >= opp_d:
            return 'C'
        return 'D'

    if opp_c + 8 >= opp_d and d10 <= 1:
        return 'C'

    return 'D'
